    bool snapToGrid = true;
    float snapStep = 1.0f;
    bool aiPathPreview = true;
    bool showInteractionHelpers = true;
    bool showObjectLabels = false;
    bool showGridOverlay = true;
    bool showBoundsOverlay = true;
    bool showReferenceLinks = true;
