    bool showServiceRadiusOverlay = true;
    bool autoSemanticOverlay = true;
    bool autoSemanticLayout = true;
    bool preserveManualSemanticAnchors = true;
    bool strictSemanticExport = true;
    PreviewViewportState previewViewport;
